from typing import List


class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        mod = 10**9 + 7
        if k == 0:
            return m * pow(m - 1, n, mod) % mod
        fact = [1] * n
        for i in range(1, n):
            fact[i] = fact[i - 1] * i % mod
        choose = fact[n - 1] * pow(fact[k], mod - 2, mod) % mod * pow(fact[n - 1 - k], mod - 2, mod) % mod
        return m * pow(m - 1, n - 1 - k, mod) % mod * choose % mod
